
using System.Diagnostics;
using System.Net.Http;
using System.Net.Http.Json;
using System.Net.Http.Headers;
using System.Text.Json;
using System.IO.Compression;
using System.Reflection;
using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Windows.Forms;
namespace PeoYameTray;
internal static class Program {
 static Process? backend; static NotifyIcon? tray; static ToolStripMenuItem? demoMenuItem; static readonly HttpClient http=new(); static bool demoEnabled,explicitDemoOverride;
 static string DataDir=>Environment.GetEnvironmentVariable("PEO_YAME_DATA_DIR")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Peo Yame","data");
 static string DemoSettingFile=>Path.Combine(DataDir,"demo-mode.json");
 static string PortFile=>Path.Combine(DataDir,"backend-port.txt");
 static string RuntimeRoot=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Peo Yame","runtime","v"+(Assembly.GetExecutingAssembly().GetName().Version?.ToString()??"1"));
 static string DatabaseKeyFile=>Path.Combine(DataDir,"keys","database.key.dpapi");
 static readonly int Port=ResolvePort(); static readonly object logLock=new();
 static int ResolvePort(){if(int.TryParse(Environment.GetEnvironmentVariable("PORT"),out var configured)&&configured>0)return configured;var candidates=new List<int>();try{if(int.TryParse(File.ReadAllText(PortFile).Trim(),out var saved)&&saved>0)candidates.Add(saved);}catch{}candidates.Add(47320);foreach(var candidate in candidates){try{using var listener=new TcpListener(IPAddress.Loopback,candidate);listener.Start();listener.Stop();return candidate;}catch{}}using var fallback=new TcpListener(IPAddress.Loopback,0);fallback.Start();return ((IPEndPoint)fallback.LocalEndpoint).Port;}
 static void PersistPort(){try{Directory.CreateDirectory(DataDir);File.WriteAllText(PortFile,Port.ToString());}catch{}}
 static string? ResolveLanHost(){foreach(var adapter in NetworkInterface.GetAllNetworkInterfaces().Where(x=>x.OperationalStatus==OperationalStatus.Up)){foreach(var entry in adapter.GetIPProperties().UnicastAddresses){var address=entry.Address;if(address.AddressFamily!=AddressFamily.InterNetwork||IPAddress.IsLoopback(address))continue;var bytes=address.GetAddressBytes();if(bytes[0]==10||bytes[0]==192&&bytes[1]==168||bytes[0]==172&&bytes[1]>=16&&bytes[1]<=31)return address.ToString();}}return null;}
 static void Log(string message){try{Directory.CreateDirectory(Path.Combine(DataDir,"logs"));lock(logLock)File.AppendAllText(Path.Combine(DataDir,"logs","app.log"),DateTimeOffset.Now.ToString("O")+" "+message+Environment.NewLine);}catch{}}
 [STAThread] static int Main(string[] args){var diagnostic=Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG");if(!string.IsNullOrEmpty(diagnostic))File.AppendAllText(diagnostic,"Main entered: "+string.Join(" ",args)+Environment.NewLine);if(args.Contains("--self-test")){try{return SelfTest().GetAwaiter().GetResult();}catch(Exception e){var log=Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG")??Path.Combine(Path.GetTempPath(),"PeoYame-self-test.log");File.WriteAllText(log,e.ToString());return 2;}}using var instance=new Mutex(true,"Local\\PeoYameTray",out var firstInstance);if(!firstInstance)return 0;ApplicationConfiguration.Initialize();Directory.CreateDirectory(DataDir);explicitDemoOverride=Environment.GetEnvironmentVariable("PEO_YAME_DEMO_ENABLED") is not null;demoEnabled=ResolveDemoMode(args);
 var menu=new ContextMenuStrip();menu.Items.Add("Launch web app",null,async(_,_)=>await StartAsync());menu.Items.Add("Restart backend",null,async(_,_)=>await RestartAsync());menu.Items.Add("Stop",null,(_,_)=>StopBackend());demoMenuItem=new ToolStripMenuItem("Demo mode"){CheckOnClick=true,Checked=demoEnabled,Enabled=!explicitDemoOverride};demoMenuItem.CheckedChanged+=async(_,_)=>{if(explicitDemoOverride)return;demoEnabled=demoMenuItem.Checked;PersistDemoMode();UpdateTrayMode();try{await RestartForModeChangeAsync();}catch(Exception error){Log("Could not change Demo mode: "+error);tray!.BalloonTipTitle="Demo mode could not be changed";tray.BalloonTipText=error.Message;tray.ShowBalloonTip(6000);}};menu.Items.Add(demoMenuItem);menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Quit",null,(_,_)=>{StopBackend();tray!.Visible=false;Application.Exit();});
 var ico=Assembly.GetExecutingAssembly().GetManifestResourceStream("PeoYame.ico");Icon appIcon;if(ico is null)appIcon=(Icon)System.Drawing.SystemIcons.Application.Clone();else{using(ico)appIcon=new Icon(ico);}tray=new NotifyIcon{Text=TrayText(),Icon=appIcon,ContextMenuStrip=menu,Visible=true};tray.DoubleClick+=async(_,_)=>await StartAsync();Application.ApplicationExit+=(_,_)=>StopBackend();Application.Idle+=StartAtLaunch;Application.Run();return 0;}
 static string TrayText()=>demoEnabled?"Peo Yame · Demo mode is on":"Peo Yame · Demo mode is off";
 static void UpdateTrayMode(){if(tray is not null)tray.Text=TrayText();if(demoMenuItem is not null&&demoMenuItem.Checked!=demoEnabled)demoMenuItem.Checked=demoEnabled;}
 static bool ResolveDemoMode(string[] args){var configured=Environment.GetEnvironmentVariable("PEO_YAME_DEMO_ENABLED");if(configured is not null){if(!bool.TryParse(configured,out var value)){Log("PEO_YAME_DEMO_ENABLED must be true or false; ignoring the invalid value.");return false;}return value;}if(args.Contains("--demo"))return true;if(File.Exists(DemoSettingFile))return string.Equals(File.ReadAllText(DemoSettingFile).Trim(),"true",StringComparison.OrdinalIgnoreCase);return false;}
 static void PersistDemoMode(){Directory.CreateDirectory(DataDir);var temporary=DemoSettingFile+".tmp";File.WriteAllText(temporary,demoEnabled?"true":"false");File.Move(temporary,DemoSettingFile,true);}
 static async void StartAtLaunch(object? sender,EventArgs e){Application.Idle-=StartAtLaunch;Log("Desktop launcher startup initiated.");try{await StartAsync();}catch(Exception error){Log("Startup failed: "+error);if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log)File.AppendAllText(log,"Desktop launcher startup failed: "+error+Environment.NewLine);tray!.BalloonTipTitle="Peo Yame did not start";tray.BalloonTipText=error.Message;tray.ShowBalloonTip(6000);}}
 static string DashboardUrl=>$"http://127.0.0.1:{Port}/";
 static void OpenDashboard(){if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log)lock(logLock)File.AppendAllText(log,"Dashboard launch target: "+DashboardUrl+Environment.NewLine);if(Environment.GetEnvironmentVariable("PEO_YAME_NO_BROWSER")=="true")return;if(Process.Start(new ProcessStartInfo(DashboardUrl){UseShellExecute=true}) is null)throw new Exception("Windows could not open the Peo Yame dashboard.");}
 static async Task StartAsync(){await StartBackendAsync(false);OpenDashboard();}
 static async Task RestartAsync(){StopBackend();await StartBackendAsync(true);OpenDashboard();}
 static async Task RestartForModeChangeAsync(){StopBackend();await StartBackendAsync(false);OpenDashboard();}
 static void EnsureRuntime(){if(File.Exists(Path.Combine(RuntimeRoot,"node.exe"))&&File.Exists(Path.Combine(RuntimeRoot,"src","server.js")))return;var zipPath=RuntimeRoot+".zip";var tempRoot=RuntimeRoot+".extracting";Directory.CreateDirectory(Path.GetDirectoryName(RuntimeRoot)!);if(Directory.Exists(tempRoot))Directory.Delete(tempRoot,true);try{using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("PeoYame.bundle.zip")??throw new FileNotFoundException("The embedded Peo Yame backend is missing."))using(var output=File.Create(zipPath))input.CopyTo(output);Directory.CreateDirectory(tempRoot);ZipFile.ExtractToDirectory(zipPath,tempRoot);if(!File.Exists(Path.Combine(tempRoot,"node.exe"))||!File.Exists(Path.Combine(tempRoot,"src","server.js")))throw new InvalidDataException("The embedded Peo Yame backend package is incomplete.");if(Directory.Exists(RuntimeRoot))Directory.Delete(RuntimeRoot,true);Directory.Move(tempRoot,RuntimeRoot);}finally{try{File.Delete(zipPath);}catch{}try{if(Directory.Exists(tempRoot))Directory.Delete(tempRoot,true);}catch{}}}
 static string LoadDatabaseKey(){var entropy=Encoding.UTF8.GetBytes("Peo Yame database key v1");Directory.CreateDirectory(Path.GetDirectoryName(DatabaseKeyFile)!);byte[] key;if(File.Exists(DatabaseKeyFile)){key=ProtectedData.Unprotect(File.ReadAllBytes(DatabaseKeyFile),entropy,DataProtectionScope.CurrentUser);}else{key=RandomNumberGenerator.GetBytes(32);var encrypted=ProtectedData.Protect(key,entropy,DataProtectionScope.CurrentUser);var temporary=DatabaseKeyFile+".tmp";File.WriteAllBytes(temporary,encrypted);File.Move(temporary,DatabaseKeyFile);CryptographicOperations.ZeroMemory(encrypted);}if(key.Length!=32){CryptographicOperations.ZeroMemory(key);throw new CryptographicException("The protected database key has an invalid length.");}try{return Convert.ToHexString(key);}finally{CryptographicOperations.ZeroMemory(key);CryptographicOperations.ZeroMemory(entropy);}}
 static async Task StartBackendAsync(bool reset){if(backend is {HasExited:false})return;EnsureRuntime();var root=RuntimeRoot;var node=Path.Combine(root,"node.exe");var psi=new ProcessStartInfo(node,"src/server.js"){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true};psi.Environment["PEO_YAME_DATA_DIR"]=DataDir;psi.Environment["PEO_YAME_DB_KEY"]=LoadDatabaseKey();psi.Environment["PORT"]=Port.ToString();psi.Environment["HOST"]="127.0.0.1";var lanHost=ResolveLanHost();if(lanHost is not null)psi.Environment["PEO_YAME_LAN_HOST"]=lanHost;else psi.Environment.Remove("PEO_YAME_LAN_HOST");var configuredDemo=Environment.GetEnvironmentVariable("PEO_YAME_DEMO_ENABLED");psi.Environment["PEO_YAME_DEMO_ENABLED"]=configuredDemo??(demoEnabled?"true":"false");if(reset)psi.Environment["PEO_YAME_RESET_INSTANCE"]="true";psi.RedirectStandardOutput=true;psi.RedirectStandardError=true;backend=Process.Start(psi)??throw new Exception("Windows could not start the embedded Peo Yame backend.");backend.OutputDataReceived+=(s,e)=>{if(e.Data!=null){Log(e.Data);if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log)lock(logLock)File.AppendAllText(log,e.Data+Environment.NewLine);}};backend.ErrorDataReceived+=(s,e)=>{if(e.Data!=null){Log("Backend: "+e.Data);if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log)lock(logLock)File.AppendAllText(log,e.Data+Environment.NewLine);}};backend.BeginOutputReadLine();backend.BeginErrorReadLine();for(var i=0;i<40;i++){if(backend.HasExited)throw new Exception("The embedded backend stopped during startup.");try{using var r=await http.GetAsync($"http://127.0.0.1:{Port}/api/health");if(r.IsSuccessStatusCode){PersistPort();UpdateTrayMode();return;}}catch{}await Task.Delay(500);}throw new Exception("Peo Yame backend did not become ready. See %LOCALAPPDATA%\\Peo Yame\\logs for startup details.");}
 static void StopBackend(){try{if(backend is {HasExited:false}){backend.Kill(true);backend.WaitForExit(5000);}}catch{}backend=null;}
 static async Task<int> SelfTest(){var temp=Path.Combine(Path.GetTempPath(),"peoyame-ci-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);var oldData=Environment.GetEnvironmentVariable("PEO_YAME_DATA_DIR");var oldPort=Environment.GetEnvironmentVariable("PORT");Environment.SetEnvironmentVariable("PEO_YAME_DATA_DIR",temp);Environment.SetEnvironmentVariable("PORT",Port.ToString());try{using(var icon=Assembly.GetExecutingAssembly().GetManifestResourceStream("PeoYame.ico")){if(icon is null||icon.Length<1024)throw new Exception("The approved Windows app icon was not embedded.");}await StartBackendAsync(false);using var ok=await http.GetAsync("http://127.0.0.1:"+Port+"/api/health");if(!ok.IsSuccessStatusCode)throw new Exception("start/health failed");using var dashboard=await http.GetAsync("http://127.0.0.1:"+Port+"/");if(!dashboard.IsSuccessStatusCode||!(await dashboard.Content.ReadAsStringAsync()).Contains("<title>Peo Yame</title>"))throw new Exception("dashboard did not launch");OpenDashboard();using var reg=await http.PostAsJsonAsync("http://127.0.0.1:"+Port+"/api/account/register",new{name="Lifecycle Farmer",phone="71234567",password="lifecycle-check-password"});if(!reg.IsSuccessStatusCode)throw new Exception("registration failed");using var regJson=JsonDocument.Parse(await reg.Content.ReadAsStringAsync());var token=regJson.RootElement.GetProperty("token").GetString()!;using var siteRequest=new HttpRequestMessage(HttpMethod.Post,"http://127.0.0.1:"+Port+"/api/sites");siteRequest.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);siteRequest.Content=JsonContent.Create(new{name="Lifecycle store",crop="Maize"});using var siteResponse=await http.SendAsync(siteRequest);if(!siteResponse.IsSuccessStatusCode)throw new Exception("site setup failed");StopBackend();await StartBackendAsync(true);using var restart=await http.GetAsync("http://127.0.0.1:"+Port+"/api/health");if(!restart.IsSuccessStatusCode)throw new Exception("restart failed");using var login=await http.PostAsJsonAsync("http://127.0.0.1:"+Port+"/api/account/login",new{phone="71234567",password="lifecycle-check-password"});if(!login.IsSuccessStatusCode)throw new Exception("restart did not preserve login account");using var loginJson=JsonDocument.Parse(await login.Content.ReadAsStringAsync());var newToken=loginJson.RootElement.GetProperty("token").GetString()!;using var sitesRequest=new HttpRequestMessage(HttpMethod.Get,"http://127.0.0.1:"+Port+"/api/sites");sitesRequest.Headers.Authorization=new AuthenticationHeaderValue("Bearer",newToken);using var sitesResponse=await http.SendAsync(sitesRequest);using var sitesJson=JsonDocument.Parse(await sitesResponse.Content.ReadAsStringAsync());if(sitesJson.RootElement.GetArrayLength()!=0)throw new Exception("restart did not reset instance locations");StopBackend();try{using var stopped=await http.GetAsync("http://127.0.0.1:"+Port+"/api/health");throw new Exception("stop left the server responding");}catch(HttpRequestException){}return 0;}catch(Exception e){var message=e.ToString();File.WriteAllText(Path.Combine(temp,"self-test.log"),message);if(Environment.GetEnvironmentVariable("PEO_YAME_SELF_TEST_LOG") is string log)File.AppendAllText(log,message+Environment.NewLine);StopBackend();return 1;}finally{Environment.SetEnvironmentVariable("PEO_YAME_DATA_DIR",oldData);Environment.SetEnvironmentVariable("PORT",oldPort);if(!File.Exists(Path.Combine(temp,"self-test.log"))){try{Directory.Delete(temp,true);}catch{}}}}
}
